export type ItemGame = 'oot' | 'mm' | 'shared';
export type ItemCategory =
  | 'equipment' | 'items' | 'songs' | 'rewards'
  | 'masks' | 'bottles' | 'souls_boss' | 'souls_enemy' | 'souls_npc' | 'souls_misc' | 'misc' | 'label' | 'button' | 'keys';

export interface TrackerItem {
  id: string;
  name: string;
  icon: string;
  game: ItemGame;
  category: ItemCategory;
  maxLevel: number;
  settingKey?: string;
  levelLabels?: (string | null)[];
  levelIcons?: string[];
  showCount?: boolean;
  step?: number;
  startUndimmed?: boolean;
  startLabel?: string;
  /** Number of individual notes required to complete this song in songShuffle=notes mode */
  noteCount?: number;
}

